/* eqfont.js — a Helvetica-metric font that has the rupee sign.

   jsPDF's built-in Helvetica is encoded WinAnsi, and the Indian rupee sign
   (U+20B9) is not in WinAnsi — so every "₹" the documents printed vanished
   from the shared PDF, leaving bare numbers and a column header reading
   "Crs, except EPS in".

   Substituting "Rs." would have been the cheap answer and the wrong one: an
   Indian research report prints the symbol. So this embeds one.

   It is Liberation Sans, which is metrically identical to Helvetica and Arial
   — the fonts the documents are laid out in — with the rupee glyph grafted in
   from DejaVu Sans, both being drawn on a 2048-unit em so the outline carries
   across unchanged. Subset to the characters these reports actually use, the
   pair comes to about 20KB, against 740KB for DejaVu whole.

   Metrics matter here beyond neatness: the writer positions every line at the
   x the BROWSER measured, so a font whose advances differ from the browser's
   would put right-aligned figures in the wrong place. Liberation's do not.
*/
(function () {
  'use strict';
  window.EQFont = {
  "EQSans-Regular.ttf": "",
  "EQSans-Bold.ttf": ""
  };
})();
